// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.assume(newLog != address(0));

        // Any actor can initialize the contract.
        vm.prank(actor);
        c.Initialized();

        // Rule: after initialization, SetLogFile must always revert for every actor/address.
        vm.prank(actor);
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}
